/* Host FXAA on the final present copy. TJ_HOST_AA=1/0 forces it; otherwise
 * it follows TJ_DISABLE_MLAA=1 (guest Edge MLAA skipped). Read once. */
static int host_aa_enabled(void)
{
    static int cached = -1;
    if (cached < 0) {
        const char* v = getenv("TJ_HOST_AA");
        if (v && (v[0] == '0' || v[0] == '1') && v[1] == '\0') {
            cached = v[0] == '1';
        } else {
            const char* m = getenv("TJ_DISABLE_MLAA");
            cached = (m && m[0] == '1' && m[1] == '\0') ? 1 : 0;
        }
    }
    return cached;
}

/* ---------------------------------------------------------------------------
 * Constants
 * -----------------------------------------------------------------------*/

/* Swap-chain buffer capacity. s_d3d.swap_buffer_count is the count in use:
 * 2 (double buffering) unless TJ_PRESENT_PHASE=1 selects 3 (see
 * s_present_phase). Per-buffer arrays and index bounds use the capacity. */
#define FRAME_COUNT         3
#define FRAME_COUNT_DEFAULT 2
#define MAX_VERTICES    393216  /* measured heavy frames exceed 64K vertices */
#define MAX_DRAWS         2048  /* measured worst case is about 1,841 draws */
#define DRAW_TEXTURE_COUNT (RSX_MAX_TEXTURES + RSX_MAX_VERTEX_TEXTURES)
#define VP_TEX_SNAPSHOT_MAX_BYTES       (128ull * 1024ull * 1024ull)
#define VP_TEX_SNAPSHOT_SINGLE_MAX_BYTES (32ull * 1024ull * 1024ull)
#define VP_TEX_SNAPSHOT_HASH_REUSE_MIN_BYTES (16u * 1024u)
#define VP_TEX_SNAPSHOT_BUCKETS 1024u
#define VP_TEX_SNAPSHOT_HINTS 256u
#define VP_TEX_SNAPSHOT_HINT_WAYS 4u
#define VP_TEX_SNAPSHOT_RETAIN_MAX_BYTES (64ull * 1024ull * 1024ull)
#define VP_TEX_SNAPSHOT_RETAIN_MAX_ENTRIES 256u
#define SAMPLER_KEY_WORDS 8u   /* address/control/filter/border/compare/border-type/format/remap */
/* Per-draw VP constant-buffer slot: vp_c[512] + posscale + posoffset +
 * branch/output/clip controls + four vertex-texture scales (8304 B), rounded up to
 * D3D12's 256-byte CBV alignment.
 * Constants are snapshotted at RECORD time -- wave's passes each set their
 * own texScale/offset uniforms, so one per-frame snapshot ran every pass
 * with the LAST pass's constants. */
#define VP_CB_STRIDE      8448
/* b1 is draw-private: 16 tex scales, 16 packed texture-control words,
 * alpha/output, raster, WPOS, and fog control, then every inline FP CONST payload as exact
 * host-order uint4 words. Four control words share each uint4 slot. */
#define FP_CB_TEXTURE_CONTROL_SLOTS 4u
#define FP_CB_ALPHA_SLOT  (RSX_MAX_TEXTURES + FP_CB_TEXTURE_CONTROL_SLOTS)
#define FP_CB_RASTER_SLOT (FP_CB_ALPHA_SLOT + 1u)
#define FP_CB_WINDOW_SLOT (FP_CB_RASTER_SLOT + 1u)
#define FP_CB_FOG_SLOT    (FP_CB_WINDOW_SLOT + 1u)
#define FP_CB_INLINE_BASE (FP_CB_FOG_SLOT + 1u)
#define FP_CB_STRIDE       (((FP_CB_INLINE_BASE + RSX_FP_MAX_INLINE_CONSTANTS) * 16u + 255u) & ~255u)
#define VERTEX_STRIDE       36  /* bytes per host vertex: pos3 + col4 + uv2 */

/* Record-time guest texture bytes.  A replay can happen after later RSX work
 * overwrote the same guest address, so metadata alone is not a texture
 * snapshot. Blobs are immutable, content-deduplicated and refcounted by draw
 * records and uploaded texture-cache slots. Cache retention stays inside the
 * same byte budget. The optional Windows write-watch path can prove unchanged
 * source pages; unavailable/dirty observations retain complete byte checks. */
typedef struct VPTexSnapshot {
    struct VPTexSnapshot* hash_next;
    struct VPTexSnapshot* hint_next;
    u8* data;
    u32 bytes;
    u32 source_off; /* address of the installed hint; never content validity */
    u64 hash;
    u32 refs;
    u8 pool_retained; /* a strong owner lives in the bounded FIFO pool */
    /* TJ_LOOKUP_FASTPATH: last vp_tex slot + 1 bound to this snapshot, or 0.
     * A probe hint only; the full slot identity check decides every hit. */
    u16 tex_cache_slot_plus1;
    u64 source_write_stamp; /* nonzero only after a tracked source observation */
    RsxTextureWriteStampHint source_stamp_hint;
    /* PC key prompts (PS3RECOMP_PROMPT_ART, see tj_prompt_apply): the latched
     * bindings signature this snapshot was last checked against, and a WEAK
     * pointer to its key-cap override, valid only while prompt_sig equals the
     * latched signature (the atlas entry owns the override). */
    u64 prompt_sig;
    struct VPTexSnapshot* prompt_override;
    u8 is_override; /* host-built override: never in buckets, hints or pool */
} VPTexSnapshot;

typedef struct {
    u32 vb_byte_offset; /* offset into vb_mapped where this draw's verts live */
    u32 vertex_count;
    u32 topology;       /* D3D_PRIMITIVE_TOPOLOGY_* */
    int textured;       /* 1 = sample the bound font/atlas texture (dbgfont) */
    int is_vp;          /* 1 = real VP path: vb_byte_offset indexes vp_vb (float4) */
    /* Fixed BasicVertex fallback is record-private too.  It must never replay
     * against the final RSX matrix/state after later FIFO records changed it. */
    int legacy_state_captured;
    float legacy_mvp[16];
    /* VP path per-draw shader/texture state, captured at draw_arrays time. */
    u32 fp_addr;        /* SET_SHADER_PROGRAM value (guest FP ucode location)   */
    u32 fp_resolved_off;/* record-time resolved guest offset, or FFFFFFFF */
    int fp_exp32;       /* SET_SHADER_CONTROL 32-bit-exports bit at draw time   */
    int fp_srgb;        /* SET_SHADER_PACKER, valid for half exports to integer RTs */
    u32 fp_input_control; /* texcoord 2D bits [9:0], two-sided colour bit 10 */
    /* Captured at record time. Same fp_addr can have its inline CONST words
     * patched before a later draw, so replay must never inspect live ucode. */
    int fp_program_valid;
    RSXFPStructuralProgram fp_program;
    u32 alpha_ctl;      /* alpha test: enable<<16 | (func&0xFF)<<8 | ref */
    u32 cmask;          /* D3D write mask from SET_COLOR_MASK at draw time
                         * (wave's sim passes write single lanes of the height
                         * maps; ignoring the mask stomped persistent state) */
    /* Complete NV4097 fragment texture bank, captured at draw time. */
    struct {
        u32 off;        /* resolved vm offset (guest upload source), 0 = none */
        u32 raw;        /* raw RSX offset (offscreen-RT matching) */
        u32 w, h, depth, fmt; /* dimensions + RSX base format */
        u16 mips;       /* exact clamped mip count from SET_TEXTURE_FORMAT */
        int cube;       /* SET_TEXTURE_FORMAT bit 2 */
        u32 dimension;  /* 1=1D, 2=2D, 3=3D, 4=cube */
        u32 location;   /* format[1:0]: 1 = LOCAL, 2 = MAIN */
        u32 pitch;      /* NV4097 TEX_SIZE1 linear source row pitch */
        u32 ctrl1;      /* NV4097 TEXTURE_CONTROL1: component remap crossbar */
        u32 address;    /* NV4097 TEXTURE_ADDRESS */
        u32 control0;   /* NV4097 TEXTURE_CONTROL0 */
        u32 filter;     /* NV4097 TEXTURE_FILTER */
        u32 border_color; /* NV4097 TEXTURE_BORDER_COLOR */
        u8 border_type; /* SET_TEXTURE_FORMAT bit 3; source porch = !this */
        int set;
    } tex[RSX_MAX_TEXTURES];
    VPTexSnapshot* tex_snapshot[RSX_MAX_TEXTURES];
    u32 tex_snapshot_fault_mask;
    int tex_rt[RSX_MAX_TEXTURES]; /* OffRT/display/history/snapshot ownership */
    /* Separate NV4097 vertex texture bank. Vertex TXL addresses units 0..3;
     * they occupy shared SRVs t16..t19 and vertex-only samplers s0..s3, so
     * neither aliases fragment state. */
    struct {
        u32 off, raw, w, h, depth, fmt;
        u16 mips;
        int cube;
        u32 dimension;
        u32 location, pitch, ctrl1, address, control0, filter, border_color;
        u8 border_type; /* source porch = !this */
        int set;
    } vtex[RSX_MAX_VERTEX_TEXTURES];
    VPTexSnapshot* vtex_snapshot[RSX_MAX_VERTEX_TEXTURES];
    u32 vtex_snapshot_fault_mask;
    int vtex_rt[RSX_MAX_VERTEX_TEXTURES];
    int tex_slot;       /* legacy single-slot path (atlas); -1 = none */
    int vs_idx;         /* VPVSEntry slot for this draw's vertex program (-1 = primary) */
    int blend;          /* guest blend enable at draw time */
    u32 blend_key;      /* packed guest blend state (factors+equation), PSO key */
    u32 mrt_key;        /* four D3D write-mask nibbles + MRT1/2/3 blend enables */
    u32 blend_color;    /* 8-bit AARRGGBB or 16-bit RG constant */
    u32 blend_color2;   /* 16-bit BA constant */
    u8 logic_key;       /* enable + D3D12_LOGIC_OP */
    INT depth_bias;     /* topology-selected RSX polygon offset units */
    float slope_scaled_depth_bias;
    /* TJ_RENDER_SCALE host factor of the attachment this record rasterizes
     * into (colour if it writes colour, else zeta). Fixed at record time with
     * the WPOS lane and slope bias that depend on it; 0/1 means 1x. */
    u8 raster_scale;
    u32 depth_key;      /* enable | write<<1 | RSX compare func<<8 (PSO key) */
    int depth_bounds_enable;
    float depth_bounds_min, depth_bounds_max;
    float wpos_scale_y, wpos_bias_x, wpos_bias_y;
    float fog_param0, fog_param1;
    u32 fog_mode;
    u64 stencil_key;    /* enable + compare/masks/ops (PSO key) */
    u8 stencil_ref;     /* dynamic OM stencil reference */
    u8 back_stencil_ref;/* dynamic back-face reference when command-list8 exists */
    u8 cull_key;        /* enable + front/back/both + winding (PSO key) */
    /* Global 20-descriptor sampler-table ID: fragment s0-s15 followed by
     * vertex s0-s3. Page = ID / capacity; slot = ID % capacity. Each
     * shader-visible D3D12 sampler heap is limited to 2048 descriptors, so a
     * frame can span multiple sampler-heap pages. */
    u16 sampler_table;
    /* Render-to-texture identity is (rt_off, rt_local). (0, LOCAL) is a
     * display/sentinel; (0, MAIN) is a valid offscreen allocation. */
    u32 rt_off;
    /* Registered display targets retain their raw RSX identity instead of
     * collapsing all of them into the host swap-chain backbuffer. */
    u32 rt_display_raw;
    int rt_is_display;     /* distinguishes registered raw 0 from no display */
    u32 rt_mrt[3];      /* colour targets B,C,D (MRT1/2/3), 0 = none. Deferred
                         * shading G-buffers write 3-4 targets in one pass. */
    u32 rt_w, rt_h;     /* surface clip dims at record time (offscreen RT size) */
    u32 rt_fmt;         /* RSX surface colour format (SET_SURFACE_FORMAT [4:0]) */
    u32 rt_target;      /* raw SET_SURFACE_COLOR_TARGET value */
    u32 rt_raw[4];      /* A/B/C/D offsets before backend display collapsing */
    u32 rt_pitch[4];    /* A/B/C/D pitches for mip/alias diagnosis */
    u8  rt_raw_local[4];/* A/B/C/D context-DMA locations at record time */
    u8  rt_local;       /* selected colour target context-DMA location */
    u8  rt_mrt_local[3];/* B/C/D context-DMA locations */
    u32 zeta_raw, zeta_pitch;
    u8  zeta_local;
    u8  zeta_format;
    u8  depth_slot;     /* DSV descriptor index; 0 = default display depth */
    u32 rt_clip_x, rt_clip_y, rt_clip_w, rt_clip_h;
    u32 rt_window_x, rt_window_y;
    u32 scissor_x, scissor_y, scissor_w, scissor_h;
    float clip_min, clip_max;
    /* Guest viewport at draw time, in target pixels.  D3D12 consumes the
     * rectangle directly (top-left origin, positive height) and the clip
     * range as MinDepth/MaxDepth. */
    u32 vp_x, vp_y, vp_w, vp_h;
    /* Ordered clear op (offscreen surfaces only; display clears stay the
     * frame-start backbuffer clear). is_clear records also set is_vp so the
     * legacy replay pass skips them. */
    int   is_clear;
    u32   clear_flags;
    float clear_depth;
    u8    clear_stencil;
    /* Ordered NV3089 exact RGBA copy.  It has no vertices and is replayed
     * between neighbouring draw records, never from the FIFO walker. */
    int   is_scaled_blit;
    RsxD3D12ExactBlit scaled_blit;
    /* Endpoint allocation is preflighted once before any replay mutation.
     * Immutable MAIN source snapshots must never be materialised a second
     * time during replay: those slots are record-private. */
    int scaled_blit_prepared;
    int scaled_blit_direct_readback;
    int scaled_blit_src_kind, scaled_blit_src_slot;
    int scaled_blit_dst_kind, scaled_blit_dst_slot;
    /* Snapshot authority while sequential preflight is at this record. Never
     * consult a mirror's final batch state for an earlier source. */
    int scaled_blit_src_authoritative;
    /* A fresh display source was accepted only because an earlier FIFO record
     * is scheduled to produce it. Replay must observe that production. */
    int scaled_blit_src_display_requires_fifo_dirty;
    int scaled_blit_src_display_requires_fifo_content;
    int scaled_blit_executed;
    int display_color_produced;
    int tex_display_parent_requires_fifo[RSX_MAX_TEXTURES];
    int tex_display_parent_slot[RSX_MAX_TEXTURES];
    /* Latest contributing copy is diagnostic-only; replay re-proves the full
     * prepared/executed union rather than trusting one record. */
    int tex_display_parent_record[RSX_MAX_TEXTURES];
    u32 scaled_blit_src_x, scaled_blit_src_y;
    u32 scaled_blit_dst_x, scaled_blit_dst_y;
    float cc[4];
} D3D12DrawRecord;

/* Offscreen render target (render-to-texture). Persistent across frames --
 * pass N's output is sampled by pass N+1 and possibly by later frames. */
typedef struct {
    ID3D12Resource*       res;
    ID3D12Resource*       sample;      /* ordered copy for read/write alias */
    ID3D12Resource*       up;          /* init-upload staging (kept alive) */
    u32                   off, w, h;   /* raw RSX offset + physical backing dims */
    u8                    local;       /* context-DMA location: 1 local, 0 main */
    u32                   logical_w, logical_h; /* clip size before packed placement */
    u32                   raw_pitch;   /* SET_SURFACE_COLOR_PITCH bytes */
    u32                   dxgi;        /* DXGI_FORMAT of the resource */
    u8                    rsx_fmt;     /* SET_SURFACE_FORMAT colour encoding */
    D3D12_RESOURCE_STATES st;          /* tracked resource state */
    D3D12_RESOURCE_STATES sample_st;
    int                   used;        /* referenced this frame */
} OffRT;
#define MAX_OFF_RTS  16  /* demosaic double-buffers its 6-surface pass chain */

/* RSX zeta allocations are persistent surfaces just like colour targets.
 * Keep depth/stencil contents by raw zeta identity instead of clearing one
 * shared host texture whenever the colour target changes. */
typedef struct {
    ID3D12Resource* res;
    u32 raw, pitch, w, h;   /* guest identity and extent; never host size */
    u8 local;
    u8 format;
    u8 scale;               /* sticky TJ_RENDER_SCALE host factor (desc = w/h x scale) */
    int valid;
    int initialized;
    int sample_dirty;
    u32 first_write_record_plus_one;
    rsx_d3d12_depth_sample sample;
} DepthSurface;
#define MAX_DEPTH_SURFACES 31 /* descriptor 0 remains the display fallback */
#define TEX_DEPTH_SAMPLE_BASE (-512)

typedef struct {
    u32 x, y, w, h, record;
} DisplayCoverageRect;
#define MAX_DISPLAY_COVERAGE_RECTS 32

/* A registered display raw is a real local-memory surface.  Keep one GPU
 * texture per raw; `sample` is an ordered read-old copy for self sampling. */
typedef struct {
    ID3D12Resource*       res;
    ID3D12Resource*       sample;
    u32                   raw, pitch, w, h; /* guest registration; never host size */
    u8                    scale;            /* TJ_RENDER_SCALE: res/sample = w/h x scale */
    D3D12_RESOURCE_STATES st, sample_st;
    /* Content, not allocation, validity. Fresh host-black backing must never
     * become an authoritative display/history source. */
    int                   valid;
    int                   fifo_dirty;
    u8                    fifo_coverage_count, fifo_coverage_overflow;
    u8                    plan_coverage_count, plan_coverage_overflow;
    DisplayCoverageRect    fifo_coverage[MAX_DISPLAY_COVERAGE_RECTS];
    DisplayCoverageRect    plan_coverage[MAX_DISPLAY_COVERAGE_RECTS];
} DisplaySurface;
#define MAX_DISPLAY_SURFACES CELL_GCM_MAX_DISPLAY_BUFFER_NUM

/* Main/local addresses that participate in a supported NV3089 exact copy but
 * are neither registered displays nor known OffRTs retain GPU ownership here.
 * Guest RAM remains updated by rsx_scaled_blit; these resources only preserve
 * command-order visibility for later GPU producers/consumers. */
typedef struct {
    ID3D12Resource*       res;
    ID3D12Resource*       up;
    u32                   raw, pitch, w, h, dxgi;
    u8                    local;
    int                   immutable_source;
    int                   authoritative; /* propagated only from GPU-owned input */
    u32                   canonical_ea;
    u64                   canonical_span;
    u64                   mapping_generation;
    D3D12_RESOURCE_STATES st;
    int                   valid;
    /* Preflight creates mirrors for the whole batch before replay.  Zero means
     * no FIFO write is planned; otherwise this is first writer record + 1. */
    u32                   first_write_record_plus_one;
    u64                   allocation_bytes;
} GpuMirror;
#define MAX_GPU_MIRRORS 16

/* Allocation-only cache. Entries have already completed GPU execution and
 * carry no guest address, mapping generation, snapshot, or ownership identity. */
#define GPU_SCRATCH_SLOTS 32
#define GPU_SCRATCH_MAX_BYTES (128ULL << 20)
enum { GPU_SCRATCH_MIRROR = 1, GPU_SCRATCH_READBACK = 2 };
typedef struct {
    ID3D12Resource* res;
    ID3D12Resource* up;
    D3D12_RESOURCE_STATES st;
    u32 kind, w, h;
    u64 bytes;
} GpuScratchAllocation;
static GpuScratchAllocation s_gpu_scratch[GPU_SCRATCH_SLOTS];
static u64 s_gpu_scratch_bytes, s_gpu_scratch_hits, s_gpu_scratch_misses;
static u64 s_gpu_scratch_evictions;
static u32 s_gpu_scratch_cursor;

/* One-frame only readback plans.  They are deliberately not GPU mirrors:
 * resources and optional packed output are preallocated before replay. Mapped
 * readback views survive only until cleanup after the guarded guest commit. */
typedef struct {
    ID3D12Resource* readback;
    u8* packed_argb;
    const u8* mapped_rgba;     /* mapped after fence; unmapped outside exclusive */
    u8* baseline;
    u8* guest_rows;             /* resolved before guest_world_exclusive */
    u64 mapping_generation;
    u64 canonical_span;
    u64 packed_bytes;
    u64 allocation_bytes;
    u32 record;
    u32 mapping_raw;
    u32 canonical_raw;
    u32 canonical_ea;
    u32 guest_ea;
    u32 guest_pitch;
    u32 mirror_slot;
    u32 x, y, w, h;
    u32 readback_pitch;
    u32 dxgi;
    u32 trace_source_flags;    /* retained preflight provenance; diagnostic only */
    int queued;
    int direct_readback;
    int mapped_commit;        /* captured at allocation; independent of source */
    int readback_mapped;      /* successful Map ownership, even if pointer null */
} ExactBlitWritebackPlan;

static ExactBlitWritebackPlan s_exact_writeback[MAX_DRAWS];
static u32 s_exact_writeback_count;
/* Shader-visible SRV heap layout: fixed atlas first, then cache ranges, then
 * 16-wide per-draw t0-t15 windows. Keep every base derived from its predecessor. */
#define LEGACY_ATLAS_SRV_SLOT 0
/* 96 slots overflowed when a whole busy frame replays as one batch (early
 * texture labels): late HUD draws got no texture ("guest texture slots
 * exhausted"). 384 keeps a full frame of distinct textures per batch. */
#define VP_TEX_SLOTS 384
#define VP_TEX_SRV_BASE (LEGACY_ATLAS_SRV_SLOT + 1)
#define RT_SRV_BASE (VP_TEX_SRV_BASE + VP_TEX_SLOTS)

/* Display raw addresses are identities, not aliases of one swap-chain image.
 * Keep a persistent completed-frame texture for each registered/history raw
 * surface that is sampled while another display surface is current. */
typedef struct {
    ID3D12Resource*       res;
    u32                   raw, pitch, w, h;
    u8                    scale;  /* TJ_RENDER_SCALE: res = w/h x scale */
    D3D12_RESOURCE_STATES st;
    int                   valid;
    int                   history_alias;
} DisplayHistory;
#define MAX_DISPLAY_HISTORY (CELL_GCM_MAX_DISPLAY_BUFFER_NUM * 2)
#define TEX_DISPLAY_HISTORY_BASE (-128)
/* Per-raw display SRVs live in the draw window.  Direct reads name an earlier
 * raw; sample reads are the same raw as this draw's render target. */
#define TEX_DISPLAY_DIRECT_BASE (-256)
#define TEX_DISPLAY_SAMPLE_BASE (-320)
#define TEX_GPU_MIRROR_BASE (-384)

/* An RSX MRT may name two views of the same tiled local allocation. D3D12
 * forbids binding one resource twice as an RTV, so aliasing draws use one
 * transient render target per output attachment and copy them back in order. */
typedef struct {
    ID3D12Resource*       res;
    u32                   w, h, dxgi;
    D3D12_RESOURCE_STATES st;
} OffRTScratch;
#define MAX_OFF_RT_SCRATCH 4 /* primary A plus MRT B/C/D */

/* Packed local surfaces can expose a rectangle starting inside a larger RT
 * backing allocation. D3D12 SRVs cannot crop a Texture2D, so retain small
 * copy resources keyed by parent+rectangle. They are only recycled after
 * render_frame's opening checked fence. */
typedef struct {
    ID3D12Resource*       res;
    int                   parent;
    u32                   x, y, w, h;
    u32                   dxgi;
    D3D12_RESOURCE_STATES st;
    int                   used;
} OffRTView;
#define MAX_OFF_RT_VIEWS 32
#define TEX_RT_VIEW_BASE (-3 - MAX_OFF_RTS)
/* Per-draw SRV windows cover 16 fragment + 4 vertex texture units. */
#define DRAW_SRV_BASE (RT_SRV_BASE + MAX_OFF_RTS)
#define SRV_HEAP_SIZE (DRAW_SRV_BASE + MAX_DRAWS * DRAW_TEXTURE_COUNT)
/* One D3D12 shader-visible sampler heap may hold at most 2048 descriptors. */
#define SAMPLER_HEAP_LIMIT 2048
#define SAMPLER_TABLE_CAP (SAMPLER_HEAP_LIMIT / DRAW_TEXTURE_COUNT)
#define SAMPLER_HEAP_SIZE (SAMPLER_TABLE_CAP * DRAW_TEXTURE_COUNT)
#define SAMPLER_HEAP_PAGE_COUNT \
    ((MAX_DRAWS + SAMPLER_TABLE_CAP - 1) / SAMPLER_TABLE_CAP)
typedef char tj_srv_layout_nonoverlap[
    (LEGACY_ATLAS_SRV_SLOT == 0 &&
     VP_TEX_SRV_BASE + VP_TEX_SLOTS <= RT_SRV_BASE &&
     RT_SRV_BASE + MAX_OFF_RTS <= DRAW_SRV_BASE &&
     DRAW_SRV_BASE + MAX_DRAWS * DRAW_TEXTURE_COUNT == SRV_HEAP_SIZE) ? 1 : -1];

/* Persistent VP texture cache slot. Record-time guest bytes are fully verified
 * before reuse, so animated textures still upload while static art stays in PSR.
 * SRV lives at heap index VP_TEX_SRV_BASE+slot. */
typedef struct {
    ID3D12Resource* res;
    ID3D12Resource* up;
    u32 off, w, h, depth, fmt, pitch; /* contents + guest source pitch */
    u16 mips;
    int cube;
    u32 dimension, dxgi;
    u8 has_border;            /* source porch identity: format bit 3 is inverted */
    u64 source_hash;            /* hash of the logical guest source bytes */
    VPTexSnapshot* source_snapshot; /* owned immutable uploaded-content identity */
    int used;                   /* referenced this frame */
} VPTexSlot;
/* Unique guest textures uploaded for one replayed frame. Tokyo Jungle's title
 * background alone binds more than four textures before its UI atlas; the old
 * four-slot limit silently replaced every later texture with a null SRV, so
 * active English title/menu quads rendered fully transparent. Keep enough for
 * normal game scenes and emit a warning if a heavier frame still exceeds it. */
/* Decompiled-VS cache: one entry per distinct vertex-program ucode seen at
 * draw time (hashed). Apps switch VPs between draws (gcm/cube: its MVP cube VP
 * vs dbgfont-gcm's text VP); compiling only the first left later draws
 * transformed by the wrong program (text offscreen). */
typedef struct {
    u32 hash;               /* FNV-1a of the ucode */
    ID3DBlob* vs;
    int uses_c03;
    u16 attr_read_mask;     /* ATTRn inputs the VS reads (0xFFFF = unknown) */
    /* TJ_SHADER_PREFETCH=1 only. 0 = ready (every synchronously built slot),
     * 1 = compile job pending (vs NULL until vp_vs_resolve), 2 = compile
     * failed (consumers treat the draw exactly like vs_idx -1). */
    volatile LONG prefetch_state;
    struct TJShaderJob* prefetch_job;
    int prefetch_instrs;
} VPVSEntry;
/* 512 filled after ~13 min of Survival (bank x start x vertex-texture-dims
 * variants); once full, every new VS was recompiled per draw and discarded,
 * stalling frames for ~10 s. Entries are never evicted. */
#define VP_VS_CACHE 4096 /* stable per-draw VS slots */
#define VP_VS_INDEX_SIZE 8192 /* open-addressed hash -> slot+1, power of two */

/* Compiled guest-FP pipeline cache: decompiled VS (by cache slot) + decompiled
 * PS (fragment ucode at fp_addr). */
typedef struct {
    u32 fp_addr;
    int vs_idx;             /* VPVSEntry slot this PSO's VS came from */
    u32 vs_hash;            /* validates the slot hasn't been evicted */
    u32 gen;
    u32 blend;              /* packed guest blend key (enable+factors+eq, PSO key) */
    int nrt;                /* bound colour target count (PSO key)       */
    u32 rtfmt;              /* DXGI format of the colour targets (PSO key) */
    int exp32;              /* 32-bit-exports control bit (PSO key)       */
    u64 structural_hash;    /* FP instruction stream, excluding inline payload */
    u32 structural_size;    /* exact captured bytes, including payload slots */
    u32 inline_count;       /* shape guard for b1 inline slots */
    RSXFPStructuralProgram structural_program; /* exact non-payload shape */
    u32 cmask;              /* colour write mask (PSO key) */
    u32 mrt_key;            /* per-target write masks + secondary blend enables */
    u8 logic_key;           /* guest logic operation (PSO key) */
    INT depth_bias;         /* rasterizer constant depth bias (PSO key) */
    u32 slope_bias_bits;    /* exact float bits (PSO key) */
    u32 dsvfmt;             /* DXGI depth/stencil format (PSO key) */
    u32 depth_key;          /* guest depth enable/write/compare state (PSO key) */
    u64 stencil_key;        /* guest stencil enable/compare/masks/ops (PSO key) */
    u8 cull_key;            /* guest cull mode and front winding (PSO key) */
    u64 texture_state;      /* packed dimensions plus FP depth-compare mask */
    u32 topology_type;      /* D3D12 primitive topology class (PSO key) */
    ID3D12PipelineState* pso;
    u64 last_use;           /* LRU stamp; the PSO cache owns the sole base reference */
} VPFPEntry;
#define VP_FP_CACHE 128

/* The final PS HLSL can be identical while its PSO differs by VS, blend,
 * depth, MRT, or colour-mask state.  Keep compiled bytecode separately from
 * the full PSO key so those PSO variants do not re-run D3DCompile.  Retaining
 * the exact source makes the FNV hash only a lookup accelerator, never an
 * identity decision. */
typedef struct {
    u64 source_hash;
    size_t source_len;
    u32 compile_mode;      /* target/profile + every compile-affecting mode */
    char* source;          /* exact final HLSL, owned by this entry */
    ID3DBlob* blob;        /* owned compiled PS bytecode */
    u64 last_use;          /* LRU stamp, refreshed on every exact hit */
} VPFPBlobEntry;
#define VP_FP_BLOB_CACHE 256

/* ---------------------------------------------------------------------------
 * Internal state
 * -----------------------------------------------------------------------*/

/* Two draw-sized sets cover PSOs and per-record readbacks; the fixed allowance
 * covers the bounded surface pools. Overflow rejects the unsubmitted prefix. */
#define PREFIX_OBJECT_CAP (MAX_DRAWS * 2u + 512u)
typedef struct { u32 offset, value; } D3D12TextureLabel;
/* Storage bound for deferred texture labels; the active batch limit is
 * d3d12_texture_label_cap() (default 8, TJ_TEXTURE_LABEL_CAP 8..32). */
#define TJ_TEXTURE_LABEL_CAPACITY 32u
/* Private command/upload ownership. Only the opt-in raster-only texture-release
 * path may defer its wait while the next disjoint upload bank is prepared. */
typedef struct {
    ID3D12CommandAllocator* allocator;
    ID3D12GraphicsCommandList* list;
    ID3D12GraphicsCommandList8* list8;
    ID3D12Resource* uploads[4]; /* basic VB, VP VB, VP CB, FP CB */
    u64 upload_first[4], upload_bytes[4];
    ID3D12DescriptorHeap* srv_heap;
    u8 draw_null_srv_cached[MAX_DRAWS * DRAW_TEXTURE_COUNT];
    ID3D12DescriptorHeap* sampler_heaps[SAMPLER_HEAP_PAGE_COUNT];
    VPTexSlot textures[VP_TEX_SLOTS]; /* retained exact uploaded versions */
    u32 texture_count;
    IUnknown* objects[PREFIX_OBJECT_CAP]; /* exact COM versions used by commands */
    u32 object_count;
    ID3D12Fence* completion_fence;
    u64 fence_value;
    u32 frame_index;
    u64 sequence;
    D3D12TextureLabel labels[TJ_TEXTURE_LABEL_CAPACITY];
    u32 label_count, label_flush_kind;
    int signal_queued;
    int cpu_retirement_ready; /* MAIN commits and diagnostic observers finished */
    int phase; /* 0 free, 1 reserved/unsubmitted, 2 submitted, 3 failed/held */
    int completion_checked;
} D3D12PrefixOwner;

typedef struct {
    /* Window */
    HWND hwnd;
    u32  width;
    u32  height;
    int  window_closed;
    /* TJ_RENDER_SCALE (opt-in; 0/1 = off). width/height stay the guest size
     * every RSX-facing path uses; internal_* is the scaled display size and
     * out_* the swap chain (equal to internal_* in this slice). */
    u32  scale;
    u32  internal_w, internal_h;
    u32  out_w, out_h;

    /* D3D12 core */
    ID3D12Device*              device;
    ID3D12CommandQueue*        cmd_queue;
    IDXGISwapChain3*           swap_chain;
    ID3D12DescriptorHeap*      rtv_heap;
    u32                        rtv_descriptor_size;
    u32                        swap_buffer_count; /* <= FRAME_COUNT */
    ID3D12Resource*            render_targets[FRAME_COUNT];
    /* PS3 display buffers are distinct local-memory surfaces, but this backend
     * renders all of them into the current swap-chain backbuffer.  When a title
     * samples one display buffer while drawing the next (Tokyo Jungle's
     * Survival post-process chain), snapshot the live backbuffer here first. */
    ID3D12Resource*            display_sample;
    D3D12_RESOURCE_STATES      display_sample_state;
    DisplayHistory             display_history[MAX_DISPLAY_HISTORY];
    DisplaySurface             display_surface[MAX_DISPLAY_SURFACES];
    GpuMirror                  gpu_mirror[MAX_GPU_MIRRORS];
    ID3D12CommandAllocator*    cmd_allocators[FRAME_COUNT];
    ID3D12GraphicsCommandList* cmd_list;
    ID3D12GraphicsCommandList8* cmd_list8;
    D3D12PrefixOwner prefix_owners[2];
    u32 prefix_owner_active; /* zero or slot+1, FIFO owner only */

    /* Synchronization */
    ID3D12Fence* fence;
    HANDLE       fence_event;
    u64          fence_values[FRAME_COUNT];
    /* Actual queued Signal covering all prior queue work, or zero. */
    u64          gpu_completion_ticket;
    u64          gpu_completion_reused;
    u64          gpu_completion_fresh;
    u32          frame_index;

    /* Pipeline */
    ID3D12RootSignature*  root_signature;
    ID3D12PipelineState*  pipeline_state;         /* triangle class — default */
    ID3D12PipelineState*  pipeline_state_lines;   /* line class */
    ID3D12PipelineState*  pipeline_state_points;  /* point class */

    /* Depth/stencil */
    ID3D12DescriptorHeap* dsv_heap;
    ID3D12Resource*       depth_buffer;
    u32                   dsv_inc;
    DepthSurface          depth_surface[MAX_DEPTH_SURFACES];

    /* Dynamic vertex buffer (upload heap) */
    ID3D12Resource*       vertex_buffer;
    D3D12_VERTEX_BUFFER_VIEW vb_view;
    void*                 vb_mapped;      /* persistently mapped */
    u32                   vb_offset;      /* current write position */

    int                   pipeline_ready; /* 1 if root sig + PSO created */

    /* Debug: copy the presented backbuffer to disk as BMP for the first N
     * frames (enabled by env CELLMARK_DUMP). Lets us verify what actually
     * rendered without racing the window/process lifetime. */
    ID3D12Resource*       readback_buf;
    u32                   readback_pitch;
    int                   dump_frames_left;
    int                   dump_audit_only;

    /* Textured pipeline (dbgfont / 2D atlas quads). The font atlas is an 8-bit
     * coverage texture uploaded as R8_UNORM and sampled in the pixel shader. */
    ID3D12PipelineState*  pipeline_state_tex;   /* triangle + texture + blend */
    /* Host FXAA present pass (replaces skipped guest Edge MLAA). Own heap so
     * the shared/prefix-cloned SRV layout is unchanged. */
    ID3D12PipelineState*  pipeline_state_aa;
    ID3D12DescriptorHeap* aa_srv_heap;          /* one shader-visible slot per swap buffer */
    /* TJ_RENDER_SCALE exact copies between surfaces of different host scale:
     * box-down / nearest-up draw. Created only when the opt-in is active. */
    ID3D12PipelineState*  pipeline_state_scale_blit;
    ID3D12DescriptorHeap* scale_blit_rtv_heap;  /* one CPU RTV for the scratch */
    ID3D12Resource*       scale_blit_scratch;   /* 1x RGBA8 RT for MAIN mirror targets */
    D3D12_RESOURCE_STATES scale_blit_scratch_st;
    u32                   scale_blit_scratch_w, scale_blit_scratch_h;
    int                   scale_blit_drawn;     /* replay must rebind after the draw */
    ID3D12DescriptorHeap* srv_heap;             /* shader-visible atlas/cache/draw SRVs */
    u8                    draw_null_srv_cached[MAX_DRAWS * DRAW_TEXTURE_COUNT];
    ID3D12DescriptorHeap* sampler_heaps[SAMPLER_HEAP_PAGE_COUNT];
                                                   /* paged 20-descriptor per-draw sampler tables */
    ID3D12Resource*       tex_resource;         /* current atlas texture       */
    ID3D12Resource*       tex_upload;           /* staging buffer for uploads  */
    u32                   tex_w, tex_h;         /* dims of tex_resource         */
    int                   tex_ready;            /* 1 once an atlas is uploaded  */
    u32                   tex_src_offset;       /* guest RSX offset of atlas    */
    int                   tex_bound;            /* a texture is bound for draws */
    int                   tex_dirty;            /* re-upload needed this frame  */

    /* Real RSX vertex-program path: the captured VP is decompiled to HLSL and
     * used as the vertex shader, fed the raw float4 attrib0 + the vp_c[]
     * constant bank. This produces exact position + texcoord (vs. the frac
     * approximation). Used for the 2D/dbgfont quad draws. */
    ID3D12RootSignature*  vp_root_sig;          /* CBV(b0) + SRV table + sampler */
    ID3D12PipelineState*  pipeline_state_vp;    /* decompiled VS + atlas PS      */
    ID3D12PipelineState*  pipeline_state_vp_lines;
    ID3D12PipelineState*  pipeline_state_vp_points;
    ID3D12PipelineState*  pipeline_state_vp_color; /* decompiled VS + colour PS (untextured 3D) */
    ID3D12PipelineState*  pipeline_state_vp_color_lines;
    ID3D12PipelineState*  pipeline_state_vp_color_points;
    ID3D12PipelineState*  pipeline_state_vp_d16;
    ID3D12PipelineState*  pipeline_state_vp_d16_lines;
    ID3D12PipelineState*  pipeline_state_vp_d16_points;
    ID3D12PipelineState*  pipeline_state_vp_color_d16;
    ID3D12PipelineState*  pipeline_state_vp_color_d16_lines;
    ID3D12PipelineState*  pipeline_state_vp_color_d16_points;
    ID3D12Resource*       vp_vb;                /* raw float4 attrib0, per-frame */
    void*                 vp_vb_mapped;
    u32                   vp_vb_offset;
    ID3D12Resource*       vp_cb;                /* per-draw VP constant slots    */
    void*                 vp_cb_mapped;
    ID3D12Resource*       vp_fpcb;              /* per-draw FP b1 snapshot       */
    void*                 vp_fpcb_mapped;
    int                   vp_ready;             /* fallback VS+PSO compiled ok   */
    u32                   vp_compiled_key;      /* last fallback build attempt  */
    ID3DBlob*             vp_vs_blob;           /* kept for guest-FP PSO builds  */
    u32                   vp_gen;               /* bumped per VP recompile       */
    int                   vp_uses_c03;          /* VS references vp_c[0..3]      */
    VPTexSlot             vp_tex[VP_TEX_SLOTS]; /* per-frame VP texture slots    */
    VPVSEntry             vp_vs[VP_VS_CACHE];   /* per-draw decompiled VS cache  */
    int                   vp_vs_n;
    VPFPEntry             vp_fp[VP_FP_CACHE];   /* guest-FP PSO cache            */
    int                   vp_fp_n;
    u64                   vp_fp_clock;
    VPFPBlobEntry         vp_fp_blob[VP_FP_BLOB_CACHE]; /* final HLSL -> PS blob */
    int                   vp_fp_blob_n;
    u64                   vp_fp_blob_clock;     /* PS blob LRU stamp source   */
    u32                   srv_inc;              /* CBV_SRV_UAV descriptor size   */
    u32                   sampler_inc;
    u32                   sampler_table_count;  /* global tables across all pages */
    u32                   sampler_keys[MAX_DRAWS]
                                      [DRAW_TEXTURE_COUNT * SAMPLER_KEY_WORDS];
    /* VP path: latest texture bound per fragment unit. */
    struct { u32 off, raw, w, h, depth, fmt, dimension, location, pitch, ctrl1,
             address, control0, filter, border_color; u16 mips; u8 border_type;
             int cube; int set; }
             cur_texs[RSX_MAX_TEXTURES];
    struct { u32 off, raw, w, h, depth, fmt, dimension, location, pitch, ctrl1,
             address, control0, filter, border_color; u16 mips; u8 border_type;
             int cube; int set; }
             cur_vtexs[RSX_MAX_VERTEX_TEXTURES];

    /* Render-to-texture: offscreen RT pool + their RTV heap. */
    OffRT                 off_rt[MAX_OFF_RTS];
    OffRTScratch          off_rt_scratch[MAX_OFF_RT_SCRATCH];
    OffRTView             off_rt_view[MAX_OFF_RT_VIEWS];
    ID3D12DescriptorHeap* rt_rtv_heap;          /* OffRT + scratch RTVs (CPU only) */

    /* Frame-parity double buffering for the per-draw upload streams (vp_vb
     * vertices, vp_cb constants, vp_fpcb texscales): records for frame N+1
     * are written while frame N's GPU work may still be reading -- writes go
     * to the other half. Toggled at the end of render_frame. */
    int                   vp_parity;

    /* Per-frame draw recording */
    int                   frame_recording; /* 1 if cmd list is open for recording */
    u32                   draw_count;      /* draws this frame */
    D3D12DrawRecord       draws[MAX_DRAWS];
    u64                   vp_tex_snapshot_bytes;
    VPTexSnapshot*        vp_tex_snapshot_buckets[VP_TEX_SNAPSHOT_BUCKETS];
    VPTexSnapshot*        vp_tex_snapshot_hints[VP_TEX_SNAPSHOT_HINTS];
    VPTexSnapshot*        vp_tex_snapshot_pool[VP_TEX_SNAPSHOT_RETAIN_MAX_ENTRIES];
    u32                   vp_tex_snapshot_pool_head;
    u32                   vp_tex_snapshot_pool_count;
    u64                   vp_tex_snapshot_pool_bytes;
    int                   vp_tex_snapshot_pool_enabled;
    u32                   vp_tex_snapshot_pool_suppress;
    int                   gcm2d_batch_fault;
    /* A deferred exact copy failed after its CPU copy succeeded.  Resource
     * states may be recorded but discarded, so never resume this device. */
    int                   gcm2d_backend_halted;
    u32                   gcm2d_mirror_peak;
    const char*           gcm2d_endpoint_reason;
    /* A FIFO completion edge submits without presenting.  Keep GPU-owned
     * surfaces alive across those prefixes; only a natural Present starts a
     * new mirror epoch. */
    int                   fifo_prefix_epoch_open;
    int                   fifo_prefix_outstanding;
    u64                   fifo_prefix_serial;
    D3D12_RESOURCE_STATES backbuffer_state;
    int                   fifo_prefix_epoch_cleared;
    /* FIFO owner only. Fixed storage; no label becomes guest-visible until
     * the containing prefix has completed on the GPU. */
    D3D12TextureLabel texture_labels[TJ_TEXTURE_LABEL_CAPACITY];
    u32                   texture_label_count;
    u64                   prefix_submit_sequence, prefix_retired_sequence;
    u32                   prefix_deferred_owner; /* newest slot + 1; queue-ahead may retain both */
    u32                   prefix_prepare_owner; /* prior slot + 1 during bounded prepare/queued pair */
    u64                   prefix_prepare_admitted, prefix_prepare_pending;
    u64                   prefix_prepare_mid_drains, prefix_prepare_late_drains;
    u64                   prefix_queued_pairs;
    u64                   prefix_queue_ahead_deferred, prefix_queue_ahead_bank_drains;
    u64                   prefix_queue_ahead_record_retires;
    u64                   prefix_vertex_prepare_sequence; /* exact B retained by early vertex reuse */
    int                   prefix_overlap_request;
    int                   texture_release_nowait_request;
    int                   texture_label_armed;
    u32                   texture_label_flush_kind; /* 1 inputs, 2 draw/upload, 3 clear, 4 label limit */

    /* Pointer to current RSX state (set before draw calls) */
    const rsx_state*      current_rsx_state;

    /* Current frame state */
    float clear_color[4];  /* RGBA float */
    u32 clear_flags;
    float clear_depth;
    u8 clear_stencil;
    /* Last consumed flip generation whose content this backend submitted.
     * This is not a GPU-completion fence: render_frame() returns void. */
    u64 submitted_boundary_generation;

    /* Stats */
    u64 frame_count;
    u64 last_fps_time;
    u32 fps;

    int initialized;
} D3D12State;

static D3D12State s_d3d;

/* Opt-in texture-label batch limit. Unset/invalid keeps the original 8; only
 * the count changes, every existing publication/flush boundary is retained. */
static u32 d3d12_texture_label_cap(void)
{
    static u32 cap;
    if (!cap) {
        const char* value = getenv("TJ_TEXTURE_LABEL_CAP");
        char* end = NULL;
        long parsed = value && value[0] ? strtol(value, &end, 10) : 0;
        cap = end && !*end && parsed >= 8 && parsed <= (long)TJ_TEXTURE_LABEL_CAPACITY
            ? (u32)parsed : 8u;
        if (cap != 8u)
            fprintf(stderr, "[tj-label-cap] texture label cap %u\n", cap);
    }
    return cap;
}

static u64 vp_fp_cache_next_stamp(void)
{
    if (s_d3d.vp_fp_clock == UINT64_MAX) {
        u64 old_stamps[VP_FP_CACHE];
        int count = s_d3d.vp_fp_n;
        if (count < 0) count = 0;
        if (count > VP_FP_CACHE) count = VP_FP_CACHE;
        for (int i = 0; i < count; ++i)
            old_stamps[i] = s_d3d.vp_fp[i].last_use;

        /* Rebase by age. Equal stamps use the stable lower slot first. */
        for (int i = 0; i < count; ++i) {
            u64 rank = 1;
            for (int j = 0; j < count; ++j)
                if (old_stamps[j] < old_stamps[i] ||
                    (old_stamps[j] == old_stamps[i] && j < i))
                    ++rank;
            s_d3d.vp_fp[i].last_use = rank;
        }
        s_d3d.vp_fp_clock = (u64)count;
    }
    return ++s_d3d.vp_fp_clock;
}

static int vp_fp_cache_insert_slot(void)
{
    if (s_d3d.vp_fp_n < VP_FP_CACHE)
        return s_d3d.vp_fp_n++;

    int oldest = 0;
    for (int i = 1; i < VP_FP_CACHE; ++i)
        if (s_d3d.vp_fp[i].last_use < s_d3d.vp_fp[oldest].last_use)
            oldest = i;
    if (s_d3d.vp_fp[oldest].pso)
        s_d3d.vp_fp[oldest].pso->lpVtbl->Release(s_d3d.vp_fp[oldest].pso);
    return oldest;
}

